static int checks=0,failures=0;
static void require(bool ok,const std::string& message){checks++;if(!ok){failures++;std::cerr<<"FAIL "<<message<<'\n';}}
static bool close(double a,double b,double eps=1e-7){return std::abs(a-b)<eps;}
static CulinaryBatch mixture(std::initializer_list<std::pair<std::string,double>> ingredients){CulinaryBatch b;uint64_t op=1;for(auto& [k,n]:ingredients)addIngredient(b,k,n,1,op++);return b;}
static void run(CulinaryBatch& b,Technique t,int ticks=12,double temp=20,double shear=.8){for(int n=0;n<ticks;n++){std::vector<uint64_t> ids;for(auto& p:b.parts)ids.push_back(p.id);processBatch(b,{t,temp,shear,(t==Technique::Vacuum||t==Technique::FreezeDry)?.12:1},ids,100+b.history.size()+n);}}
static double accounted(const CulinaryBatch& b){double n=0;for(auto& p:b.parts)n+=foodMass(p.food)+p.food.lostMass;return n;}
